#include <iostream>
using namespace std;

long long factorial(int n) {
    long long r = 1;
    for (int i = 2; i <= n; i++) r *= i;
    return r;
}

long long C(int n, int k) {
    if (k > n - k) k = n - k;
    long long r = 1;
    for (int i = 0; i < k; i++) r = r * (n - i) / (i + 1);
    return r;
}

long long P(int n, int k) {
    return C(n, k) * factorial(k);
}

int main() {
    int n = 10, k = 3;
    cout << "排列 P(10,3) = " << P(n, k) << endl;
    cout << "组合 C(10,3) = " << C(n, k) << endl;
    cout << "关系 P = C × k! = " << C(n,k) << " × " << factorial(k) << " = " << P(n,k) << endl;
    return 0;
}

