#include <iostream>
using namespace std;

long long factorial_loop(int n) {
    long long result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

long long factorial_recursive(int n) {
    if (n <= 1) return 1;
    return n * factorial_recursive(n - 1);
}

int main() {
    for (int i = 0; i <= 10; i++) {
        cout << i << "! = " << factorial_loop(i) << endl;
    }
    return 0;
}

