#include <iostream>
using namespace std;

const int MOD = 1000000007;
long long C[1001][1001];

void init() {
    for (int i = 0; i <= 1000; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
        }
    }
}

int main() {
    init();
    int n = 10, k = 3;
    cout << "C(" << n << "," << k << ") = " << C[n][k] << endl;
    long long sum = 0;
    for (int j = 0; j <= n; j++) sum = (sum + C[n][j]) % MOD;
    cout << "sum C(10,k) = " << sum << endl;
    return 0;
}

