#include <iostream>
using namespace std;

long long C(int n, int k) {
    if (k > n - k) k = n - k;
    long long r = 1;
    for (int i = 0; i < k; i++) r = r * (n - i) / (i + 1);
    return r;
}

int main() {
    int n = 5;
    cout << "(a+b)^" << n << " 的系数：";
    for (int k = 0; k <= n; k++) {
        cout << C(n, k);
        if (k < n) cout << " ";
    }
    cout << endl;
    long long sum = 0;
    for (int k = 0; k <= n; k++) sum += C(n, k);
    cout << "系数之和 = " << sum << " = 2^" << n << " = " << (1 << n) << endl;
    return 0;
}

